-- 137: Original BrillaPrep WASSCE BrillaPrep transitional Applied Electricity beta content blueprint beta questions, part 8.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_137_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_137_guard;
INSERT INTO _migration_137_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_elect_b001_036' AND NOT (q.topic_id IS 'topic_was_elect_8' AND q.subject_id IS 'subj_wassce_elect_app' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the main safety purpose of protective earthing?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Make all conductors carry normal load current through earth","B. Increase touch voltage during a fault","C. Replace overcurrent protection","D. Provide a low-impedance fault path so protection disconnects exposed metal"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Earthing connects exposed conductive parts so a fault current can operate protective devices quickly and limit dangerous touch voltage. Therefore the correct answer is D: Provide a low-impedance fault path so protection disconnects exposed metal.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_elect_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_elect_b001_036' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Applied Electricity practice; not official WAEC examination material and not the new Applied Technology III bank.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2026/03/FINAL-TIMETABLE-FOR-WASSCE-SC-2026-GHANA-ONLY-NEW-TAD.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_137_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_elect_b001_037' AND NOT (q.topic_id IS 'topic_was_elect_8' AND q.subject_id IS 'subj_wassce_elect_app' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A correctly rated fuse melts during a sustained overcurrent. What protective action has it performed?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Open the circuit when current exceeds its safe value for sufficient time","B. Maintain current regardless of faults","C. Increase conductor temperature","D. Act as a normal on-off control switch"]' AND q.correct_answer IS 'A' AND q.explanation IS 'A fuse element melts under excessive current, interrupting the circuit to reduce damage and fire risk when correctly rated and installed. Therefore the correct answer is A: Open the circuit when current exceeds its safe value for sufficient time.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_elect_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_elect_b001_037' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Applied Electricity practice; not official WAEC examination material and not the new Applied Technology III bank.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2026/03/FINAL-TIMETABLE-FOR-WASSCE-SC-2026-GHANA-ONLY-NEW-TAD.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_137_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_elect_b001_038' AND NOT (q.topic_id IS 'topic_was_elect_8' AND q.subject_id IS 'subj_wassce_elect_app' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which device is designed to detect an imbalance between line and neutral currents?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Energy meter","B. Residual current device","C. Step-up transformer","D. Series resistor"]' AND q.correct_answer IS 'B' AND q.explanation IS 'An RCD compares outgoing and returning current and disconnects when leakage exceeds its trip threshold, supplementing other protection. Therefore the correct answer is B: Residual current device.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_elect_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_elect_b001_038' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Applied Electricity practice; not official WAEC examination material and not the new Applied Technology III bank.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2026/03/FINAL-TIMETABLE-FOR-WASSCE-SC-2026-GHANA-ONLY-NEW-TAD.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_137_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_elect_b001_039' AND NOT (q.topic_id IS 'topic_was_elect_8' AND q.subject_id IS 'subj_wassce_elect_app' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is electrical power transmitted at high voltage?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. High voltage makes conductors have no resistance","B. It removes the need for insulation","C. Higher voltage permits lower current and lower I²R loss for the same power","D. It makes transformers unnecessary"]' AND q.correct_answer IS 'C' AND q.explanation IS 'For a given power, raising voltage lowers current, and resistive line loss falls with the square of current, subject to insulation and equipment requirements. Therefore the correct answer is C: Higher voltage permits lower current and lower I²R loss for the same power.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_elect_8' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_elect_b001_039' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Applied Electricity practice; not official WAEC examination material and not the new Applied Technology III bank.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2026/03/FINAL-TIMETABLE-FOR-WASSCE-SC-2026-GHANA-ONLY-NEW-TAD.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_137_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_elect_b001_040' AND NOT (q.topic_id IS 'topic_was_elect_8' AND q.subject_id IS 'subj_wassce_elect_app' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In Ghana’s nominal 400/230 V low-voltage system, what voltage is supplied between one phase and neutral?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. About 400 V","B. About 11 kV","C. Exactly 0 V","D. About 230 V"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Ghana’s nominal low-voltage distribution levels are 400 V phase-to-phase and 230 V phase-to-neutral, so a single-phase consumer receives about 230 V. Therefore the correct answer is D: About 230 V.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_elect_8' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_elect_b001_040' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Applied Electricity practice; not official WAEC examination material and not the new Applied Technology III bank.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2026/03/FINAL-TIMETABLE-FOR-WASSCE-SC-2026-GHANA-ONLY-NEW-TAD.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
